// W13 · Job — что пришло из W3 «Route» (15.10.2026, docs/recommendations.md): кнопка rs: | ru: | rq: | rp: | rr:
// (data — callback_data как есть) или ответ на вопрос RESUME_PROMPTS (op input, field, text). Ручной запуск — панель.
// Нода: Code, режим «Run Once for All Items».
// Выход: { op, sid, index, value, field, text, chatId, queryId, messageId, userMessageId, promptId }
//   rs:view → view · rs:up → upgrade · rs:file → file · rs:undo → undo (rs:undo:y — откатить)
//   ru:<sid>:<y|e|n> → plan: верно | не так | отмена
//   rq:<sid>:go → start · rq:<sid>:x → stop · rq:<sid>:<вопрос>:<0-7|t|k|d> → answer: вариант | свой ответ | пропустить | готово
//   rp:<sid>:<правка>:<y|r|a|e|n> → patch: применить | заменить | дописать | иначе | не надо
//   rr:<sid> → retry — повторить запрос к нейросети

const j = $input.first().json;
const out = {
  op: j.op ?? 'view',
  sid: '',
  index: -1,
  value: String(j.value ?? ''),
  field: String(j.field ?? ''),
  text: String(j.text ?? ''),
  chatId: String(j.chatId || $env.TG_CHAT_ID),
  queryId: String(j.queryId ?? ''),
  messageId: Number(j.messageId) || 0,
  userMessageId: Number(j.userMessageId) || 0,
  promptId: Number(j.promptId) || 0,
};
const data = String(j.data ?? '');
let m;
if ((m = data.match(/^rs:(view|an|up|file|undo)(?::(y))?$/))) {
  out.op = { view: 'view', an: 'analyze', up: 'upgrade', file: 'file', undo: 'undo' }[m[1]];
  out.value = m[2] ?? '';
} else if ((m = data.match(/^ru:([a-z0-9]{4}):([yen])$/))) {
  Object.assign(out, { op: 'plan', sid: m[1], value: m[2] });
} else if ((m = data.match(/^rq:([a-z0-9]{4}):(go|x)$/))) {
  Object.assign(out, { op: m[2] === 'go' ? 'start' : 'stop', sid: m[1] });
} else if ((m = data.match(/^rq:([a-z0-9]{4}):(\d):([0-7tkd])$/))) {
  Object.assign(out, { op: 'answer', sid: m[1], index: Number(m[2]), value: m[3] });
} else if ((m = data.match(/^rp:([a-z0-9]{4}):(\d):([yraen])$/))) {
  Object.assign(out, { op: 'patch', sid: m[1], index: Number(m[2]), value: m[3] });
} else if ((m = data.match(/^rr:([a-z0-9]{4})$/))) {
  Object.assign(out, { op: 'retry', sid: m[1] });
} else if (data) {
  out.op = 'view';
}
return [{ json: out }];

// W13 · Plan — событие человека → сессия правки → куда дальше (15.10.2026, docs/recommendations.md).
// Нода: Code, режим «Run Once for All Items». Вход: «Job», «Settings», static data (сессия).
// Выход: { route: llm | file | step, mode, rows, wait, comment, keep, stale }
//   llm  — спросить нейросеть: mode analyze (анализ: отчёт и вопросы) | plan (план Upgrade) | patch (правки) | rework
//          (переделать одну правку, comment — пожелание, keep — «➕ Не заменять, дописать»); wait — { messageId, text }:
//          что показать, пока нейросеть думает;
//   file — резюме файлом;
//   step — остальное: «Step» покажет, что теперь в сессии;
//   rows — нужны строки вакансий (покрытие навыков: панель и итог); stale — кнопка от прошлой сессии.
// Здесь — переходы по кнопкам и ответам человека; ответы нейросети разбирает «Step».
//
// Сессия (static data session): { sid, kind: upgrade | analyze, at, base — отпечаток резюме на старте, original и
//   draft — { resume, extra }, instruction, notes — «не так» к плану, plan, planOk, report — отчёт анализа, started —
//   вопросы анализа начаты, planMsg и planText — сообщение с планом или отчётом, moved — вопросы и правки уже на новой
//   панели, questions, qi, answers, picks — галочки текущего вопроса, patches, pi, dropped, applied, done — итог без
//   правок (ответы только на подсказки), last — последний запрос к нейросети { mode, comment, keep } для «🔄 Повторить» }.
// Вопрос: { text, kind: one | many | text, options, area, hint — подсказка про фильтры hh (ответ — совет, не правка),
//   tip, code: skills | where — вопросы кода про недостающие навыки, names — навыки без частоты }.
// panelId (static data) — сообщение-панель, которую правим.

// Время человека (13.10.2026, docs/onboarding.md): часовой пояс — настройка profile.tz (IANA, например Asia/Bangkok),
// иначе пояс компьютера (USER_TZ из .env — его пишет мастер установки), иначе Москва. Расписание сбора по-прежнему
// считается по Москве (n8n/shared/schedule.js): hh публикует вакансии по МСК.
// Общий код: строка «// @include n8n/shared/time.js» — раньше n8n/shared/card.js и n8n/shared/robot.js (им нужен TZ).
// Пояс берётся из ноды «Settings», если она есть в workflow и уже выполнилась; без неё — USER_TZ.

const MSK_TZ = 'Europe/Moscow';
const validTz = (tz) => {
  try {
    return Boolean(tz) && Boolean(new Intl.DateTimeFormat('en-GB', { timeZone: tz }));
  } catch {
    return false;
  }
};

// Пояс этого запуска
function currentTz() {
  let tz = '';
  try {
    const row = $('Settings')
      .all()
      .map((i) => i.json)
      .find((r) => r?.name === 'profile.tz');
    tz = row ? JSON.parse(row.value_json) : '';
  } catch {
    // в workflow нет ноды «Settings» или строка битая — пояс компьютера
  }
  const env = typeof $env === 'undefined' ? '' : $env.USER_TZ;
  return [tz, env, MSK_TZ].find(validTz);
}
const TZ = currentTz();

// Части даты в поясе tz числами: { y, mo, d, h, mi }
function zonedParts(ms, tz = TZ) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).formatToParts(new Date(ms));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return { y: get('year'), mo: get('month'), d: get('day'), h: get('hour'), mi: get('minute') };
}
const pad2 = (n) => String(n).padStart(2, '0');

// 1760340720000 → '14:32'
const localHM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.h)}:${pad2(p.mi)}`;
};
// → '07.10'
const localDM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.d)}.${pad2(p.mo)}`;
};
// → '2026-10-07' — ключ дня
const localDay = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${p.y}-${pad2(p.mo)}-${pad2(p.d)}`;
};
const localHour = (ms, tz = TZ) => zonedParts(ms, tz).h;

// Смещение пояса от UTC в минутах в момент ms (Бангкок: +420)
function tzOffsetMin(ms, tz = TZ) {
  const p = zonedParts(ms, tz);
  return Math.round((Date.UTC(p.y, p.mo - 1, p.d, p.h, p.mi) - Math.floor(ms / 60000) * 60000) / 60000);
}

// 'UTC+7', 'UTC+5:30', 'UTC−4'
function tzLabel(tz = TZ, ms = Date.now()) {
  const off = tzOffsetMin(ms, tz);
  const abs = Math.abs(off);
  return `UTC${off < 0 ? '−' : '+'}${Math.floor(abs / 60)}${abs % 60 ? `:${pad2(abs % 60)}` : ''}`;
}

// Начало «дня», который начинается в hour:00 по местному: последний такой момент не позже ms
function localDayStart(ms, tz = TZ, hour = 0) {
  const p = zonedParts(ms, tz);
  let start = Date.UTC(p.y, p.mo - 1, p.d, hour) - tzOffsetMin(ms, tz) * 60000;
  if (start > ms) start -= 24 * 3600 * 1000;
  return start;
}

// Тихие часы 23:00–09:00 по местному: карточки и сводка — без звука, тревоги — со звуком
const quietHours = (ms = Date.now(), tz = TZ) => {
  const h = localHour(ms, tz);
  return h >= 23 || h < 9;
};

// Время по местному и в скобках по Москве: '14:32 (10:32 МСК)'; пояс совпадает с Москвой — '10:32 МСК'
const localMsk = (ms, tz = TZ) =>
  tzOffsetMin(ms, tz) === tzOffsetMin(ms, MSK_TZ) ? `${localHM(ms, MSK_TZ)} МСК` : `${localHM(ms, tz)} (${localHM(ms, MSK_TZ)} МСК)`;

// Момент ISO (applied_at) → дата и время по местному: '2026-10-06T21:17:55Z' → '07.10', '04:17'
const localDate = (iso) => (Date.parse(iso) ? localDM(Date.parse(iso)) : '');
const localTime = (iso) => (Date.parse(iso) ? localHM(Date.parse(iso)) : '');

// Общий код карточки вакансии в Telegram: W2 «Format card» и W3 «Apply choice».
// В Code-ноду попадает при сборке: строка «// @include n8n/shared/card.js» заменяется этим файлом
// (scripts/build-workflows.mjs, scripts/run-code-node.mjs). Раньше него — n8n/shared/time.js (localDate).

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const EXPERIENCE = { noExperience: 'без опыта', between1And3: '1–3 г.', between3And6: '3–6 л.', moreThan6: '6+ л.' };
const CURRENCY = { RUR: '₽', USD: '$', EUR: '€', KZT: '₸', BYR: 'Br', UZS: 'сум' };

// Решение нейросети (колонка decision)
const VERDICT = { apply: '🟢 apply', maybe: '🟡 maybe', skip: '🔴 skip', error: '⚠️ не оценено' };
// Кнопки пользователя: callback_data = v:<id строки>:<choice>, решение — в колонку my_decision.
// earlier — «📨 Уже откликался» (до бота, 07.10.2026): status = applied без письма и без applied_at,
// без «Почему?» и вне теневого режима (сравниваются только apply / maybe / skip)
const CHOICE = { apply: '✅ Откликнусь', maybe: '🤔 Возможно', skip: '❌ Мимо', earlier: '📨 Откликался раньше' };
// «🚫 В ЧС» на карточке (07.10.2026): компания уходит в чёрный список, вакансия — ❌ с этой причиной
const BAN_REASON = 'чёрный список';
const STATUS_BY_CHOICE = { apply: 'approved', maybe: 'maybe', skip: 'skipped', earlier: 'applied' };

const short = (n) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n));

function salary(r) {
  if (!r.salary_from && !r.salary_to) return '';
  const range =
    r.salary_from && r.salary_to
      ? `${short(r.salary_from)}–${short(r.salary_to)}`
      : r.salary_from
        ? `от ${short(r.salary_from)}`
        : `до ${short(r.salary_to)}`;
  return `💰 ${range} ${CURRENCY[r.currency] ?? r.currency ?? ''}${r.salary_gross ? ' до налогов' : ''}`;
}

// «Москва, Сербия, Грузия, Армения» → «Москва, Сербия +2»
function areas(s) {
  const list = String(s ?? '').split(', ').filter(Boolean);
  return list.length > 2 ? `${list.slice(0, 2).join(', ')} +${list.length - 2}` : list.join(', ');
}

// '2026-10-06T13:22:00+0300' → '06.10'
function published(s) {
  const m = String(s ?? '').match(/^\d{4}-(\d{2})-(\d{2})/);
  return m ? `${m[2]}.${m[1]}` : '';
}

// Итоговые состояния без кнопок: W3 «📨 Отправил», W6 «⌛ устарела» и «🔒 закрыта на hh»
const FINAL = { expired: '⌛ Устарела: 3 дня без решения', archived: '🔒 Вакансия закрыта на hh' };

// Текст карточки (Parse Mode = HTML). Строка «👤 …» появляется после нажатия кнопки,
// «📨 …» — после «Отправил» под письмом (W3, status = applied), FINAL — после W6
function cardText(r) {
  const date = published(r.published_at);
  const meta = [esc(r.company), salary(r), EXPERIENCE[r.experience] ?? '', esc(areas(r.areas)), date && `📅 ${date}`]
    .filter(Boolean)
    .join(' · ');
  const flags = [
    r.has_test && '📝 тест',
    r.letter_required && '✉️ письмо обязательно',
    r.responses != null && `👥 ${r.responses}`,
    r.error && `⚠️ ${esc(r.error)}`,
  ]
    .filter(Boolean)
    .join(' · ');
  // Нейросеть не оценивала, а фильтр отсеял (в том числе вакансия, возвращённая с панели меню, 08.10.2026) — причины фильтра
  const verdict =
    !r.decision && r.reasons
      ? `🧹 Отсеяна фильтром: ${esc(r.reasons)}`
      : `🤖 ${VERDICT[r.decision] ?? esc(r.decision)}${r.llm_reason ? ` — ${esc(r.llm_reason)}` : ''}`;
  const mine = CHOICE[r.my_decision]
    ? `👤 ${CHOICE[r.my_decision]}${r.my_reason === BAN_REASON ? ' · 🚫 компания в чёрном списке' : ''}`
    : '';
  // «📨 Откликался раньше» уже в строке «👤 …» — второй раз не пишем
  // Робот (этап 6): «🚀 … роботом»; нашёлся на hh без «📨 Отправил» (6.2) — «📨 … на hh»
  const who = r.apply_by === 'robot' ? '🚀 Отклик отправлен роботом' : r.apply_by === 'hh' ? '📨 Отклик есть на hh' : '📨 Отклик отправлен';
  const sent =
    r.status === 'applied' && r.my_decision !== 'earlier' ? `${who}${r.applied_at ? ` ${localDate(r.applied_at)}` : ''}` : '';
  return [`<a href="${r.url}"><b>${esc(r.title)}</b></a>`, meta, flags, verdict, mine, sent, FINAL[r.status] ?? '']
    .filter(Boolean)
    .join('\n');
}

// Настройки из бота (⚙️ Настройки, решения пользователя 07.10.2026): схема, значения по умолчанию, чтение.
// В таблице settings (name, value_json) лежат только изменения пользователя: пустая таблица — значения по умолчанию,
// то есть поведение до появления настроек. Значение, которое не проходит проверку схемы, заменяется значением
// по умолчанию — битая строка в таблице не ломает сбор.
// Общий код W1, W2, W5, W6, W7, W8, W9: строка «// @include n8n/shared/settings.js» (перед n8n/shared/schedule.js).

// Правила фильтра W1, которые можно выключить (filter.rules_off): id → подпись. «В архиве» не выключается
const FILTER_RULES = {
  no_exp: 'без опыта',
  junior: 'junior/стажёр',
  angular: 'Angular',
  lead: 'Lead/архитектор',
  stop: 'стоп-слова',
  foreign: 'чужой стек',
  backend: 'бэкенд',
  blacklist: 'чёрный список',
  only_rf: 'только из РФ',
  no_stack: 'нет React и Vue',
};
// Правила фронтенда (пресет frontend, 13.10.2026): у остальных профессий они отсекли бы всё — не работают
// и не показываются в ⚙️
const FRONTEND_FILTER_RULES = ['angular', 'foreign', 'backend', 'no_stack'];
// Правила фильтра для пресета: id → подпись
const filterRulesFor = (preset) =>
  Object.fromEntries(Object.entries(FILTER_RULES).filter(([id]) => preset === 'frontend' || !FRONTEND_FILTER_RULES.includes(id)));

const SETTINGS = {
  // Сбор (W8 Clock): интервал днём и ночью (мин, 0 — ночью не собирать), «день» по Москве, пауза
  'collect.day_every': { default: 30, options: [15, 30, 60] },
  'collect.night_every': { default: 120, options: [60, 120, 240, 0] },
  'collect.day_window': { default: '07-18', options: ['07-18', '08-20', '06-22', '09-18'] },
  'collect.paused': { default: false, options: [false, true] },
  // Поиск на hh (W1, n8n/shared/search.js): период в днях; слова везде в тексте и только в названии.
  // Слов «везде» может не быть (ищем только по названию) — «-» в ответе на ✏️ очищает список
  'search.period': { default: 1, options: [1, 3, 7] },
  'search.anywhere': { default: ['frontend'], words: true, min: 0 },
  'search.in_name': {
    default: ['react', 'next.js', 'nextjs', 'vue', 'vue.js', 'vuejs', 'nuxt', 'nuxt.js', 'nuxtjs', 'typescript',
      'AI', 'ИИ', 'LLM', 'GenAI', 'GPT', 'нейросети', 'нейросетей'],
    words: true,
  },
  // Роли hh (professional_role, n8n/shared/hh-roles.js), формат работы, город для офиса и гибрида, образование —
  // онбординг пишет их по резюме (13.10.2026, docs/onboarding.md). Удалёнка ищется по всем регионам, офис и гибрид —
  // в городе search.area: два запроса hh
  'search.roles': { default: ['96'], roles: true },
  'search.formats': { default: ['REMOTE'], formats: true },
  'search.area': { default: null, area: true },
  'search.education': { default: ['not_required_or_not_specified'], education: true },
  // Фильтр W1: порог откликов (0 — не отсекать), выключенные правила, стоп-слова в названии («*» — любое окончание)
  'filter.max_responses': { default: 3000, options: [1000, 2000, 3000, 5000, 0] },
  'filter.rules_off': { default: [], list: Object.keys(FILTER_RULES) },
  'filter.stop_words': {
    min: 0,
    default: ['php*', 'laravel', 'symfony', 'yii', 'wordpress', 'bitrix*', 'битрикс*', 'qa', '1c', '1с', 'teacher',
      'tutor', 'instructor', "o'qituvchi", 'oqituvchi', 'преподавател*', 'тестировщик*', 'наставник*'],
    words: true,
  },
  // Нейросеть (W2, W5): провайдер; теневой режим — карточки и на skip (выкл — skip только в сводке)
  'llm.provider': { default: 'gemini', options: ['gemini', 'claude'] },
  'llm.shadow': { default: true, options: [true, false] },
  // Спорные случаи — список «случай: решение» (✏️, решение пользователя 07.10.2026: текстом, а не кнопками).
  // По умолчанию — четыре встроенных случая промпта W2 с их решениями; отличие от них уходит в промпт
  // «Поправками кандидата» (n8n/w2-score/build-prompt.js)
  'llm.cases': {
    default: [
      { case: 'Vue без React', decision: 'maybe' },
      { case: 'fullstack', decision: 'maybe' },
      { case: 'AI на JS/TS', decision: 'apply' },
      { case: 'React Native', decision: 'skip' },
    ],
    cases: true,
  },
  // Робот-отклик (этап 6, docs/stages/stage-6.md): кнопка 🚀 под новыми письмами, пауза очереди,
  // лимит живых откликов в «день» робота (с 09:00 по местному). Предохранитель APPLY_LIVE — в .env, не здесь
  'apply.enabled': { default: false, options: [false, true] },
  'apply.paused': { default: false, options: [false, true] },
  'apply.daily_limit': { default: 25, options: [10, 15, 25, 40] },
  // Профиль (13.10.2026, docs/onboarding.md): резюме и факты о человеке. Пишет онбординг W11 (резюме PDF в боте)
  // или импорт (node scripts/n8n-api.mjs profile-import). Умолчания — поведение до онбординга: онбординг
  // записывает все свои строки явно. Пресет frontend — откалиброванные правила владельца в коде (W2, W5)
  'profile.ready': { default: false, options: [false, true] },
  // Первый поиск после онбординга — без карточек: W2 копит оценки и шлёт одно итоговое сообщение (14.10.2026,
  // решение пользователя). Ставит W11, снимает W2, когда оценивать больше нечего
  'profile.first_quiet': { default: false, options: [false, true] },
  'profile.preset': { default: 'generic', options: ['generic', 'frontend'] },
  'profile.resume': { default: '', text: 30000 },
  'profile.extra': { default: '', text: 4000 },
  // Факты из резюме (имя и его родительный падеж, должность, компании, пол — только если указан в резюме…)
  'profile.facts': { default: {}, object: true },
  // Строки «О кандидате» промпта W2
  'profile.about': { default: [], lines: 400 },
  // Часовой пояс человека (IANA): время в боте, тихие часы, «день» робота, сводка в 10:00 (n8n/shared/time.js).
  // Пусто — пояс компьютера (USER_TZ из .env), иначе Москва
  'profile.tz': { default: '', tz: true },
  'profile.signature': { default: '', text: 60 },
  'profile.contact': { default: '', text: 160 },
  // Правила оценки пресета generic — из резюме (W11): { skip, maybe, apply, ignore, notes } — списки строк
  'llm.rules': { default: {}, rules: true },
  // Письма (W5): свои образцы и замена разделов промпта { intro, facts, style } (у владельца — из импорта)
  'letters.examples': { default: '', text: 4000 },
  'letters.prompt': { default: {}, object: true },
  // Рекомендации по резюме (W13, 15.10.2026, docs/recommendations.md): прежние версии резюме для «↩️ Откатить» —
  // до 5 { at, by, note, resume, extra }, новые сверху. Пишет только W13
  'resume.history': { default: [], history: 5 },
};

// Встроенные спорные случаи промпта W2: как узнать их в списке пользователя, решение по умолчанию
// и формулировка для поправки
const BUILTIN_CASES = {
  vue: {
    aliases: ['vue без react', 'vue', 'nuxt', 'vue/nuxt', 'vue nuxt'],
    default: 'maybe',
    prompt: 'основной стек — Vue (Vue.js, Nuxt), а React нет в обязательных требованиях',
  },
  fullstack: {
    aliases: ['fullstack', 'full stack', 'full-stack', 'фулстек', 'фуллстек', 'fullstack с react'],
    default: 'maybe',
    prompt: 'fullstack: в обязательных требованиях и React, и бэкенд на любом языке',
  },
  ai_js: {
    aliases: ['ai на js/ts', 'ai на js', 'ai на ts', 'ai js/ts', 'ai js', 'ai', 'разработка на ai'],
    default: 'apply',
    prompt: 'разработка на AI на JS/TS (Node.js, NestJS, TypeScript): интеграции LLM, AI-агенты, RAG',
  },
  react_native: {
    aliases: ['react native', 'react-native', 'rn'],
    default: 'skip',
    prompt: 'мобильная разработка на React Native — основная работа',
  },
};
const normCase = (text) =>
  String(text ?? '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/\s+/g, ' ')
    .trim();
// Встроенный случай, которому соответствует запись пользователя, или null
const builtinOf = (text) =>
  Object.keys(BUILTIN_CASES).find((key) => BUILTIN_CASES[key].aliases.includes(normCase(text))) ?? null;

// Слово списка: буквы, цифры, пробел и . + # ' - ; «*» в конце — любое окончание. Без скобок и кавычек:
// они сломали бы язык запросов hh
const WORD_RE = /^[\p{L}\p{N}][\p{L}\p{N} .+#'’-]{0,28}\*?$/u;

// items — $('Settings').all() (строки таблицы settings) → { имя: значение }
function loadSettings(items) {
  const stored = {};
  for (const item of items ?? []) {
    const row = item?.json ?? item;
    if (!row?.name || !(row.name in SETTINGS)) continue;
    try {
      stored[row.name] = JSON.parse(row.value_json);
    } catch {
      // битое значение — останется по умолчанию
    }
  }
  const out = {};
  for (const [name, spec] of Object.entries(SETTINGS)) {
    const value = stored[name];
    out[name] = value !== undefined && validSetting(spec, value) ? value : spec.default;
  }
  return out;
}

function validSetting(spec, value) {
  if (spec.options) return spec.options.some((o) => o === value);
  if (spec.words) {
    return Array.isArray(value) && value.length >= (spec.min ?? 1) && value.length <= 40 && value.every((w) => WORD_RE.test(w));
  }
  if (spec.roles) return Array.isArray(value) && value.length <= 10 && value.every((id) => /^\d{1,4}$/.test(String(id)));
  if (spec.formats) return Array.isArray(value) && value.length > 0 && value.every((f) => WORK_FORMATS.includes(f));
  if (spec.area) {
    return value === null || (Boolean(value) && /^\d{1,7}$/.test(String(value.id)) && typeof value.name === 'string' && value.name.length <= 80);
  }
  if (spec.education) return Array.isArray(value) && value.every((e) => EDUCATION.includes(e));
  if (spec.list) return Array.isArray(value) && value.every((v) => spec.list.includes(v));
  if (spec.cases) {
    return (
      Array.isArray(value) &&
      value.length <= 20 &&
      value.every((c) => CASE_RE.test(c?.case ?? '') && ['apply', 'maybe', 'skip'].includes(c?.decision))
    );
  }
  if (spec.text) return typeof value === 'string' && value.length <= spec.text;
  if (spec.tz) {
    try {
      return typeof value === 'string' && Boolean(value) && Boolean(new Intl.DateTimeFormat('en-GB', { timeZone: value }));
    } catch {
      return false;
    }
  }
  if (spec.lines) return validLines(value, spec.lines);
  if (spec.history) return validHistory(value, spec.history);
  if (spec.object) return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
  if (spec.rules) {
    return (
      Boolean(value) &&
      typeof value === 'object' &&
      !Array.isArray(value) &&
      Object.entries(value).every(([key, lines]) => RULE_KEYS.includes(key) && validLines(lines, 400))
    );
  }
  return false;
}

// Форматы работы и уровни образования — значения параметров поиска hh
const WORK_FORMATS = ['REMOTE', 'HYBRID', 'ON_SITE', 'FIELD_WORK'];
const EDUCATION = ['not_required_or_not_specified', 'special_secondary', 'higher'];

// Разделы правил оценки (llm.rules) и список строк: до 20 строк, каждая — до max знаков
const RULE_KEYS = ['skip', 'maybe', 'apply', 'ignore', 'notes'];
const validLines = (lines, max) =>
  Array.isArray(lines) && lines.length <= 20 && lines.every((l) => typeof l === 'string' && l.length <= max);

// Версии резюме (resume.history): текст резюме и «Дополнительно» — в пределах profile.resume и profile.extra
const validHistory = (list, max) =>
  Array.isArray(list) &&
  list.length <= max &&
  list.every(
    (v) =>
      Boolean(v) &&
      typeof v === 'object' &&
      typeof v.at === 'string' &&
      typeof v.resume === 'string' &&
      v.resume.length <= SETTINGS['profile.resume'].text &&
      typeof (v.extra ?? '') === 'string' &&
      String(v.extra ?? '').length <= SETTINGS['profile.extra'].text,
  );

// Текст резюме для промптов W2 и W5: резюме и «Дополнительно» (то, что человек дописал сам) — своим разделом
function resumeText(s) {
  const resume = String(s['profile.resume'] ?? '').trim();
  const extra = String(s['profile.extra'] ?? '').trim();
  return extra ? `${resume}\n\n## Дополнительно\n${extra}` : resume;
}

// Спорный случай: 2–80 знаков, без угловых скобок и обратных кавычек
const CASE_RE = /^[^<>`]{2,80}$/u;
const DECISION_WORDS = {
  apply: 'apply',
  '🟢': 'apply',
  откликнусь: 'apply',
  maybe: 'maybe',
  '🟡': 'maybe',
  возможно: 'maybe',
  skip: 'skip',
  '🔴': 'skip',
  мимо: 'skip',
};

// Список спорных случаев из ответа пользователя: «Vue без React: maybe, Angular: skip» → [{ case, decision }].
// Случаи — через запятую; если в описании нужна запятая — через «;» или с новой строки. Между случаем и решением —
// «:», «=» или тире; решение — apply, maybe, skip (или 🟢 🟡 🔴, откликнусь, возможно, мимо).
// «-» — очистить список. { error } — что не так
function parseCases(text) {
  const raw = String(text ?? '').trim();
  if (raw === '-' || raw === '—') return { cases: [] };
  const parts = (/[;\n]/.test(raw) ? raw.split(/[;\n]+/) : raw.split(',')).map((x) => x.trim()).filter(Boolean);
  if (!parts.length) return { error: 'список пуст (очистить — пришли «-»)' };
  if (parts.length > 20) return { error: `случаев ${parts.length}, можно до 20` };
  const cases = [];
  for (const part of parts) {
    const m = part.match(/^(.+?)\s*[:=—–]\s*(\S+)$/u) ?? part.match(/^(.+?)\s+-\s+(\S+)$/u);
    const decision = m && DECISION_WORDS[m[2].toLowerCase()];
    if (!decision) return { error: `«${part}»: нужно «случай: решение», решение — apply, maybe или skip` };
    const name = m[1].trim();
    if (!CASE_RE.test(name)) return { error: `«${name}»: описание случая — от 2 до 80 знаков, без < > и \`` };
    const existing = cases.find((c) => normCase(c.case) === normCase(name));
    if (existing) existing.decision = decision;
    else cases.push({ case: name, decision });
  }
  return { cases };
}

// Список для показа и вопроса: «Vue без React: maybe, fullstack: maybe»
const casesText = (cases) => cases.map((c) => `${c.case}: ${c.decision}`).join(', ');

// Список слов из ответа пользователя: «frontend, react, AI» → ['frontend', 'react', 'AI'];
// { error } — если список пуст, длиннее 40 слов или в слове недопустимые символы
function parseWords(text) {
  const seen = new Map();
  for (const w of String(text ?? '').split(/[,;\n]+/).map((x) => x.trim()).filter(Boolean)) {
    if (!seen.has(w.toLowerCase())) seen.set(w.toLowerCase(), w);
  }
  const words = [...seen.values()];
  if (!words.length) return { error: 'список пуст' };
  if (words.length > 40) return { error: `слов ${words.length}, можно до 40` };
  const bad = words.find((w) => !WORD_RE.test(w));
  if (bad) return { error: `«${bad}»: только буквы, цифры, пробел и . + # ' -, «*» в конце, до 30 знаков` };
  return { words };
}

// Включить или выключить элемент списка (filter.rules_off)
const toggleListItem = (list, item) => (list.includes(item) ? list.filter((x) => x !== item) : [...list, item]);

// Слово списка → регулярка с границами слова (латиница, кириллица, цифры); «*» в конце — любое окончание
function wordsRegex(words) {
  const parts = words.map((w) => {
    const stem = w.replace(/\*$/, '').replace(/[.+#'’-]/g, (c) => `\\${c}`);
    return w.endsWith('*') ? `${stem}[a-zа-яё0-9]*` : stem;
  });
  return new RegExp(`(^|[^a-zа-яё0-9])(${parts.join('|')})([^a-zа-яё0-9]|$)`, 'i');
}

// Следующее значение по кругу — кнопка «▸» (только у настроек с вариантами)
function nextSetting(name, current) {
  const { options } = SETTINGS[name];
  return options[(options.findIndex((o) => o === current) + 1) % options.length];
}

// Расписание сбора для n8n/shared/schedule.js
function scheduleFrom(s) {
  const [dayFrom, dayTo] = String(s['collect.day_window']).split('-').map(Number);
  return {
    dayFrom,
    dayTo,
    dayEvery: s['collect.day_every'],
    nightEvery: s['collect.night_every'],
    paused: s['collect.paused'],
  };
}

// Навыки: одно и то же под разными названиями. W5 — разметка навыков вакансии по профилю (14.10.2026), W13 — какие
// навыки вакансий есть в резюме (15.10.2026). Общий код: строка «// @include n8n/shared/skills.js».

// Упоминается ли навык в тексте (text — в нижнем регистре): целым словом, с границами и для кириллицы
const mentionsSkill = (text, skill) =>
  new RegExp(`(^|[^a-zа-яё0-9])${skill.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}([^a-zа-яё0-9]|$)`).test(text);
// Другие названия того же: «React.js» = React, SQL ⊂ PostgreSQL, руководство ≈ technical leadership / mentoring
const SKILL_ALIASES = {
  sql: ['postgresql'],
  postgres: ['postgresql'],
  kuber: ['kubernetes'],
  k8s: ['kubernetes'],
  'руководство коллективом': ['technical leadership', 'mentoring'],
  'управление командой': ['technical leadership', 'mentoring'],
  наставничество: ['mentoring'],
  'английский язык': ['английский'],
};
// Все названия навыка в нижнем регистре: «SASS/SCSS», «UI/UX» — и каждое отдельно (14.10.2026: при SCSS в резюме
// письмо писало «готов разобраться в SASS/SCSS»), «React.js» — и «react»
const skillVariants = (skill) => {
  const s = skill.toLowerCase();
  const names = [s, ...(s.includes('/') ? s.split('/').map((p) => p.trim()).filter((p) => p.length > 1) : [])];
  return [...new Set([...names.flatMap((n) => [n, n.replace(/\.?js$/, '')]), ...(SKILL_ALIASES[s] ?? [])])].filter(Boolean);
};

// Рекомендации по резюме (W13, 15.10.2026, docs/recommendations.md): правки резюме и навыки вакансий.
// Общий код W13: строка «// @include n8n/shared/resume.js» после n8n/shared/card.js (esc), n8n/shared/settings.js
// (SETTINGS) и n8n/shared/skills.js (skillVariants).
//
// Резюме бота — profile.resume и profile.extra (что человек дописал сам). Нейросеть видит их одним текстом, как W2 и W5
// (resumeText): резюме, «## Дополнительно», extra. Правка — { where, old, new, why }: old — кусок этого текста дословно.
// Код находит его ровно один раз, сам решает, добавление это или замена, и применяет к черновику.

const EXTRA_HEAD = '\n\n## Дополнительно\n';

// Черновик из настроек: { resume, extra } без пробелов по краям — так их видит resumeText
const resumeDraft = (s) => ({ resume: String(s['profile.resume'] ?? '').trim(), extra: String(s['profile.extra'] ?? '').trim() });
// Один текст — как resumeText(s): его видит нейросеть, в нём ищутся правки
const resumeJoin = (d) => (d.extra ? `${d.resume}${EXTRA_HEAD}${d.extra}` : d.resume);
// Отпечаток версии: резюме поменялось за время сессии (новый PDF в W11) — правки не сохраняем
function resumeHash(d) {
  let h = 5381;
  for (const ch of `${d.resume}\u0000${d.extra}`) h = (Math.imul(h, 33) ^ ch.codePointAt(0)) >>> 0;
  return h.toString(36);
}
// Строка без переносов, не длиннее n
const oneLine = (s, n) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? `${t.slice(0, n - 1)}…` : t;
};

// ---------- Поиск куска текста ----------

// Нормализация для поиска: пробелы подряд → один, кавычки → ", тире → -, ё → е, маркеры списка → -.
// out — строка, pos — позиция каждого её знака в исходнике
function normMap(text) {
  let out = '';
  const pos = [];
  let space = false;
  for (let i = 0; i < text.length; i++) {
    let c = text[i];
    if (/\s/.test(c)) {
      if (!space && out.length) {
        out += ' ';
        pos.push(i);
      }
      space = true;
      continue;
    }
    space = false;
    if ('«»“”„"'.includes(c)) c = '"';
    else if ('—–‒−'.includes(c)) c = '-';
    else if (c === '•' || c === '·') c = '-';
    else if (c === 'ё') c = 'е';
    else if (c === 'Ё') c = 'Е';
    out += c;
    pos.push(i);
  }
  if (out.endsWith(' ')) {
    out = out.slice(0, -1);
    pos.pop();
  }
  return { out, pos };
}

// Где в тексте кусок old: { start, end } — позиции в исходнике, или { error: none | many }
function locateSnippet(text, old) {
  const needle = String(old ?? '');
  if (!needle.trim()) return { error: 'none' };
  const first = text.indexOf(needle);
  if (first >= 0) return text.indexOf(needle, first + 1) >= 0 ? { error: 'many' } : { start: first, end: first + needle.length };
  // Нейросеть поменяла пробелы, кавычки или тире — ищем без них и переводим обратно в позиции исходника
  const t = normMap(text);
  const n = normMap(needle.trim()).out;
  const at = n ? t.out.indexOf(n) : -1;
  if (at < 0) return { error: 'none' };
  if (t.out.indexOf(n, at + 1) >= 0) return { error: 'many' };
  return { start: t.pos[at], end: t.pos[at + n.length - 1] + 1 };
}

// В какой части черновика кусок: resume, extra или null — задевает обе или заголовок «Дополнительно»
function partOf(d, at) {
  if (at.end <= d.resume.length) return 'resume';
  if (d.extra && at.start >= d.resume.length + EXTRA_HEAD.length) return 'extra';
  return null;
}

// ---------- Правка ----------

// Слова для сравнения: без регистра и знаков препинания по краям («React.» = «react», «Next.js» и «C++» — целиком)
const patchWords = (s) =>
  String(s ?? '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .match(/[\p{L}\p{N}](?:[\p{L}\p{N}.+#-]*[\p{L}\p{N}+#])?/gu) ?? [];

// Добавление — все слова old по порядку остались в new. Иначе замена: что-то из старого текста пропадёт
function isAddition(old, next) {
  const a = patchWords(old);
  let i = 0;
  for (const w of patchWords(next)) if (i < a.length && w === a[i]) i++;
  return i === a.length;
}

const PATCH_MAX = 1500;
const PATCH_ERRORS = {
  none: 'не нашёл это место в тексте',
  many: 'такой кусок встречается в тексте несколько раз',
  same: 'правка ничего не меняет',
  long: 'слишком длинная правка',
  edge: 'правка задевает и резюме, и «Дополнительно»',
  limit: 'резюме вышло бы длиннее предела',
  overlap: 'то же место уже правит другая правка',
};

// Правка нейросети → { where, old, new, why, kind: add | replace, start, end } (old — точный кусок исходника) или { error }.
// Пустой old и where «Дополнительно» — новая строка в конец profile.extra (append): у человека, который «Дополнительно»
// ещё не писал, свои проекты больше некуда вписать
function checkPatch(d, p) {
  const old = String(p?.old ?? '');
  const next = String(p?.new ?? '').trim();
  const where = oneLine(p?.where, 60) || 'Резюме';
  if (!old.trim()) {
    if (!/дополнительно/i.test(where) || !next) return { error: 'none' };
    if (next.length > PATCH_MAX) return { error: 'long' };
    return { where, old: '', new: next, why: oneLine(p?.why, 200), kind: 'add', append: 'extra', start: -1, end: -1 };
  }
  if (normMap(old).out === normMap(next).out) return { error: 'same' };
  if (next.length > PATCH_MAX || old.length > PATCH_MAX * 2) return { error: 'long' };
  const text = resumeJoin(d);
  const at = locateSnippet(text, old);
  if (at.error) return { error: at.error };
  if (!partOf(d, at)) return { error: 'edge' };
  // old — точный кусок исходника: нейросеть могла поменять в нём пробелы или кавычки, применять будем к исходнику
  const exact = text.slice(at.start, at.end);
  return {
    where,
    old: exact,
    new: next,
    why: oneLine(p?.why, 200),
    kind: isAddition(exact, next) ? 'add' : 'replace',
    start: at.start,
    end: at.end,
  };
}

// Правки нейросети → { patches, dropped: [{ where, error }] }: проверенные, без пересечений, не больше max
function checkPatches(d, list, max = 8) {
  const patches = [];
  const dropped = [];
  for (const p of (Array.isArray(list) ? list : []).slice(0, max * 2)) {
    const c = checkPatch(d, p);
    if (c.error) dropped.push({ where: oneLine(p?.where, 60) || 'Резюме', error: c.error });
    else if (!c.append && patches.some((x) => c.start < x.end && x.start < c.end)) dropped.push({ where: c.where, error: 'overlap' });
    else if (patches.length < max) patches.push(c);
  }
  return { patches, dropped };
}

// Применить правку к черновику: old ищется заново — прошлая правка могла его поменять. → { draft } или { error }
function applyPatch(d, p) {
  if (p.append === 'extra') {
    const extra = d.extra ? `${d.extra}\n${p.new}` : p.new;
    return extra.length > SETTINGS['profile.extra'].text ? { error: 'limit' } : { draft: { ...d, extra } };
  }
  const at = locateSnippet(resumeJoin(d), p.old);
  if (at.error) return { error: at.error };
  const part = partOf(d, at);
  if (!part) return { error: 'edge' };
  const offset = part === 'resume' ? 0 : d.resume.length + EXTRA_HEAD.length;
  const src = d[part];
  const value = src.slice(0, at.start - offset) + p.new + src.slice(at.end - offset);
  const limit = SETTINGS[part === 'resume' ? 'profile.resume' : 'profile.extra'].text;
  if (value.length > limit) return { error: 'limit' };
  return { draft: { ...d, [part]: value } };
}

// ---------- Дифф для Telegram ----------

// Пословный дифф (HTML): <s>убрал</s> <b>добавил</b>; длинные куски без изменений сжаты до «…» с context словами вокруг
function wordDiff(old, next, context = 8, max = 1800) {
  const a = String(old ?? '').split(/\s+/).filter(Boolean);
  const b = String(next ?? '').split(/\s+/).filter(Boolean);
  const key = (w) => patchWords(w).join(' ') || w;
  const ka = a.map(key);
  const kb = b.map(key);
  // LCS: dp[i][j] — длина общей подпоследовательности хвостов a[i:] и b[j:]
  const dp = Array.from({ length: a.length + 1 }, () => new Uint16Array(b.length + 1));
  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) dp[i][j] = ka[i] === kb[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  }
  const ops = [];
  let i = 0;
  let j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && ka[i] === kb[j]) {
      ops.push(['=', b[j++]]);
      i++;
    } else if (i < a.length && (j >= b.length || dp[i + 1][j] >= dp[i][j + 1])) ops.push(['-', a[i++]]);
    else ops.push(['+', b[j++]]);
  }
  // Склеить подряд идущие слова одного вида
  const runs = [];
  for (const [t, w] of ops) {
    if (runs.at(-1)?.[0] === t) runs.at(-1)[1].push(w);
    else runs.push([t, [w]]);
  }
  const html = runs
    .map(([t, words], n) => {
      if (t === '-') return `<s>${esc(words.join(' '))}</s>`;
      if (t === '+') return `<b>${esc(words.join(' '))}</b>`;
      const first = n === 0;
      const last = n === runs.length - 1;
      const keep = (first ? 0 : context) + (last ? 0 : context);
      if (words.length <= keep + 3) return esc(words.join(' '));
      const head = first ? [] : words.slice(0, context);
      const tail = last ? [] : words.slice(-context);
      return [...head, '…', ...tail].map(esc).join(' ');
    })
    .join(' ');
  return html.length > max ? `${html.slice(0, max).replace(/<[^>]*$/, '')}…` : html;
}

// ---------- Навыки вакансий ----------

// Вакансии, которые человек выбрал или выбрал бы: ✅ 🤔 📨 или решения нет, а нейросеть сказала apply
const isTargetRow = (r) => ['apply', 'maybe', 'earlier'].includes(r.my_decision) || (!r.my_decision && r.decision === 'apply');
// Ключ навыка для подсчёта: «React.js» = «ReactJS» = «react», «HTML5» = «HTML», «postgres» = «PostgreSQL»
const SKILL_SYNONYMS = { postgres: 'postgresql', kuber: 'kubernetes', k8s: 'kubernetes' };
function skillKey(skill) {
  const s = String(skill ?? '').toLowerCase().replace(/ё/g, 'е').replace(/\s+/g, ' ').trim();
  const base = (s.length > 3 ? s.replace(/\.?js$/, '') : s).replace(/^([a-z][a-z.+#-]{2,})\d+$/, '$1');
  return SKILL_SYNONYMS[base] ?? base;
}
// Есть ли навык в тексте резюме (в нижнем регистре): как mentionsSkill, но с номером версии после — «HTML» есть в
// «HTML5/CSS3», «CSS» — тоже
const hasSkill = (text, name) =>
  skillVariants(name).some((v) =>
    new RegExp(`(^|[^a-zа-яё0-9])${v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\d*([^a-zа-яё0-9]|$)`).test(text),
  );

// Навыки вакансий против резюме. rows — строки vacancies, text — резюме одним текстом.
// → { basis: target | passed | null, vacancies, coverage (0–1 или null), top: [{ name, freq, has }], missing }
//   basis target — вакансии, которые человек выбрал (их меньше 10 — passed: все, что прошли фильтр).
//   coverage — доля частот навыков из top, которые есть в резюме
function skillStats(rows, text, top = 30) {
  const withSkills = (rows ?? []).filter((r) => r?.key_skills);
  let basis = 'target';
  let list = withSkills.filter(isTargetRow);
  if (list.length < 10) {
    basis = 'passed';
    list = withSkills.filter((r) => !['rejected', 'seen'].includes(r.status));
  }
  if (!list.length) return { basis: null, vacancies: 0, coverage: null, top: [], missing: [] };
  const counts = new Map();
  for (const r of list) {
    const seen = new Set();
    for (const raw of String(r.key_skills).split(',').map((x) => x.trim()).filter(Boolean)) {
      const key = skillKey(raw);
      if (!key || seen.has(key)) continue;
      seen.add(key);
      const c = counts.get(key) ?? { freq: 0, names: new Map() };
      c.freq++;
      c.names.set(raw, (c.names.get(raw) ?? 0) + 1);
      counts.set(key, c);
    }
  }
  const low = String(text ?? '').toLowerCase();
  const skills = [...counts.values()]
    .map((c) => {
      const names = [...c.names.entries()].sort((x, y) => y[1] - x[1]).map(([n]) => n);
      return { name: names[0], freq: c.freq, has: names.some((n) => hasSkill(low, n)) };
    })
    .sort((x, y) => y.freq - x.freq || x.name.localeCompare(y.name))
    .slice(0, top);
  const total = skills.reduce((n, x) => n + x.freq, 0);
  const got = skills.reduce((n, x) => n + (x.has ? x.freq : 0), 0);
  return { basis, vacancies: list.length, coverage: total ? got / total : null, top: skills, missing: skills.filter((x) => !x.has) };
}

const percent = (x) => `${Math.round((x ?? 0) * 100)}%`;

// Частые слова в названиях подходящих вакансий (анализ: как называть должность) → [{ word, freq }]
const TITLE_STOP = new Set(['в', 'на', 'и', 'с', 'по', 'для', 'к', 'из', 'от', 'до', 'или', 'the', 'of', 'and', 'to', 'in', 'for', 'a']);
function titleWords(rows, top = 12) {
  const list = (rows ?? []).filter(isTargetRow);
  const counts = new Map();
  for (const r of list.length >= 10 ? list : (rows ?? []).filter((x) => !['rejected', 'seen'].includes(x?.status))) {
    const words = new Set(String(r?.title ?? '').toLowerCase().replace(/ё/g, 'е').match(/[\p{L}\p{N}][\p{L}\p{N}.+#-]*/gu) ?? []);
    for (const w of words) if (!TITLE_STOP.has(w) && w.length > 1) counts.set(w, (counts.get(w) ?? 0) + 1);
  }
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, top).map(([word, freq]) => ({ word, freq }));
}

const job = $('Job').first().json;
const s = loadSettings($('Settings').all());
const state = $getWorkflowStaticData('global');
const sess = state.session ?? null;
const out = { route: 'step', mode: '', rows: false, wait: null, comment: '', keep: false, stale: false };
const panel = job.messageId || state.panelId || 0;
// «➕ Не заменять, дописать» — то же, что пожелание к правке
const KEEP_OLD = 'Ничего не убирай из старого текста этого места, только допиши новое.';

function llm(mode, text, messageId = panel, comment = '', keep = false) {
  Object.assign(out, { route: 'llm', mode, comment, keep, wait: messageId ? { messageId, text } : null });
  if (state.session) state.session.last = { mode, comment, keep };
}
const live = Boolean(sess) && job.sid === sess.sid;
function newSession(kind, d) {
  return {
    sid: Math.random().toString(36).slice(2, 6).padEnd(4, '0'),
    kind,
    at: new Date().toISOString(),
    base: resumeHash(d),
    original: d,
    draft: d,
    instruction: '',
    notes: [],
    plan: null,
    planOk: false,
    report: null,
    started: false,
    planMsg: 0,
    planText: '',
    moved: false,
    questions: [],
    qi: 0,
    answers: [],
    picks: [],
    patches: [],
    pi: 0,
    dropped: [],
    applied: 0,
    done: false,
    last: null,
  };
}
// Нужны ли правки: у Upgrade план подтверждён; у анализа есть ответ не на подсказку (подсказки — только советы)
const needsPatches = () =>
  (sess.kind === 'upgrade' && sess.planOk) || sess.answers.some((a, i) => a && !a.skipped && !sess.questions[i]?.hint);
// После вопроса про недостающие навыки — где с ними работал: в общий список навыков или в строку про пет-проекты
const whereQuestion = (names) => ({
  text: `Где ты работал с ${names.join(', ')}? «В работе» — допишу в общий список навыков, «В своих проектах» — в строку про пет-проекты. Можно своими словами, например: «${names[0]}: в такой-то компании».`,
  llmText: 'Где кандидат работал с этими навыками (в работе: общий список навыков; в своих проектах: строка про пет-проекты)',
  kind: 'one',
  options: ['🧰 В работе', '🧪 В своих проектах'],
  area: 'skills',
  hint: false,
  code: 'where',
});
const stale = () => {
  out.stale = true;
};

// Следующий вопрос или — вопросов больше нет — правки (или итог с одними подсказками)
function nextQuestion() {
  sess.qi++;
  sess.picks = [];
  if (sess.qi < sess.questions.length) return;
  if (needsPatches()) llm('patch', '✍️ Готовлю правки…');
  else finishWithout();
}
function finishWithout() {
  sess.done = true;
  out.rows = true;
}
// Следующая правка или — правок больше нет — итог (нужны вакансии: покрытие навыков до и после)
function nextPatch() {
  sess.pi++;
  if (sess.pi >= sess.patches.length) out.rows = true;
}

if (job.op === 'view') {
  out.rows = true;
} else if (job.op === 'file') {
  out.route = 'file';
} else if (job.op === 'undo') {
  // Откат — сразу панель с покрытием; незаконченная правка теряет смысл
  out.rows = job.value === 'y';
  if (job.value === 'y') state.session = null;
} else if (job.op === 'analyze') {
  // Анализ: статистика вакансий (rows) и нейросеть → отчёт и вопросы. Незаконченная сессия заменяется новой
  out.rows = true;
  const d = resumeDraft(s);
  if (s['profile.ready'] && d.resume) {
    state.session = newSession('analyze', d);
    llm('analyze', '⏳ Смотрю резюме глазами ATS и роботов hh… Это до минуты.');
  }
} else if (job.op === 'start') {
  if (!live || sess.kind !== 'analyze' || sess.started || !sess.questions.length) stale();
  else sess.started = true;
} else if (job.op === 'input' && job.field === 'upgrade') {
  const d = resumeDraft(s);
  if (s['profile.ready'] && d.resume && job.text.trim()) {
    state.session = { ...newSession('upgrade', d), instruction: job.text.trim().slice(0, 1500) };
    llm('plan', '⏳ Ищу в резюме, куда это вписать…', state.panelId || 0);
  }
} else if (job.op === 'input' && job.field === 'plan') {
  if (sess?.plan && !sess.planOk) {
    sess.notes.push(job.text.trim().slice(0, 500));
    llm('plan', '⏳ Пересобираю план…', sess.planMsg);
  } else stale();
} else if (job.op === 'input' && job.field === 'answer') {
  if (sess && sess.qi < sess.questions.length && !sess.patches.length && !sess.done) {
    sess.answers[sess.qi] = { text: job.text.trim().slice(0, 1000) };
    nextQuestion();
  } else stale();
} else if (job.op === 'input' && job.field === 'patch') {
  if (sess && sess.pi < sess.patches.length) llm('rework', '⏳ Переделываю правку…', state.panelId, job.text.trim().slice(0, 500));
  else stale();
} else if (job.op === 'plan') {
  if (!live || !sess.plan || sess.planOk) stale();
  else if (job.value === 'y') {
    sess.planOk = true;
    if (!sess.questions.length) llm('patch', `${sess.planText}\n\n✅ Верно. ⏳ Готовлю правки…`, sess.planMsg);
  } else if (job.value === 'n') {
    state.session = null;
    out.rows = true;
  }
} else if (job.op === 'stop') {
  // ⏹ Хватит — только у вопросов: правки по тем ответам, что уже есть (у Upgrade план подтверждён — правки и без них)
  if (!live || sess.patches.length) stale();
  else if (needsPatches()) llm('patch', '✍️ Готовлю правки…');
  else if (sess.answers.some((a) => a && !a.skipped)) finishWithout();
  else {
    state.session = null;
    out.rows = true;
  }
} else if (job.op === 'answer') {
  const q = live && !sess.patches.length && !sess.done && (sess.kind !== 'analyze' || sess.started) ? sess.questions[sess.qi] : null;
  if (!q) stale();
  else if (job.index === sess.qi) {
    if (/^\d$/.test(job.value) && Number(job.value) < q.options.length) {
      const i = Number(job.value);
      if (q.kind === 'many') sess.picks = sess.picks.includes(i) ? sess.picks.filter((x) => x !== i) : [...sess.picks, i];
      else {
        sess.answers[sess.qi] = { picked: [q.options[i]] };
        nextQuestion();
      }
    } else if (job.value === 'k') {
      sess.answers[sess.qi] = { skipped: true };
      nextQuestion();
    } else if (job.value === 'd') {
      sess.answers[sess.qi] = sess.picks.length ? { picked: sess.picks.map((i) => q.options[i]) } : { skipped: true };
      if (q.code === 'skills' && sess.picks.length) sess.questions.splice(sess.qi + 1, 0, whereQuestion(sess.picks.map((i) => q.names[i])));
      nextQuestion();
    }
    // t — «Свой ответ»: вопрос ForceReply задаст «Step»
  }
} else if (job.op === 'patch') {
  const p = live ? sess.patches[sess.pi] : null;
  if (!p) stale();
  else if (job.index === sess.pi) {
    if (job.value === 'y' || job.value === 'r') {
      const r = applyPatch(sess.draft, p);
      if (r.draft) {
        sess.draft = r.draft;
        p.state = 'ok';
        sess.applied++;
      } else {
        p.state = 'fail';
        p.note = PATCH_ERRORS[r.error] ?? r.error;
      }
      nextPatch();
    } else if (job.value === 'n') {
      p.state = 'skip';
      nextPatch();
    } else if (job.value === 'a') {
      llm('rework', '⏳ Дописываю, не убирая старое…', panel, KEEP_OLD, true);
    }
    // e — «Иначе»: вопрос ForceReply задаст «Step»
  }
} else if (job.op === 'retry') {
  if (live && sess.last) llm(sess.last.mode, '⏳ Пробую ещё раз…', panel, sess.last.comment, sess.last.keep);
  else stale();
}

return [{ json: out }];

